require "application_system_test_case"

class ZzProbeBrowserTest < ApplicationSystemTestCase
  test "probe countdown ticks and asks at zero" do
    quiz = build_quiz(title: "Probe")
    build_question(quiz, text: "Q1?", options: [ [ "A", true ], [ "B", false ] ])
    build_question(quiz, text: "Q2?", options: [ [ "A", true ], [ "B", false ] ])
    quiz.update!(timer_minutes: 0, timer_seconds: 6)

    visit "/moderate/quizzes/#{quiz.id}"
    click_button "Start a game"
    page.execute_script(<<~JS)
      window.__log = [];
      const orig = window.fetch;
      window.fetch = function(url, opts) {
        window.__log.push(["fetch", String(url), Math.round(performance.now())]);
        return orig.apply(this, arguments);
      };
      setInterval(() => {
        const el = document.querySelector(".stage-timer span");
        const last = window.__log[window.__log.length - 1];
        const t = el ? el.textContent : null;
        if (!window.__log.length || window.__log[window.__log.length-1][0] !== "tick" || window.__log[window.__log.length-1][1] !== t) {
          window.__log.push(["tick", t, Math.round(performance.now())]);
        }
      }, 50);
    JS
    click_button "Start"
    sleep 9
    log = page.evaluate_script("window.__log")
    puts log.map(&:inspect)
    assert_button "Next"
  end
end
